using System.Text.Json;using TownOfHost;using TownOfHost.Roles.Core;using TownOfHost.Modules;
partial class Program {
static void RenameSetup(){OptionItem.NumPresets=7;OptionItem.Reset();Options.Reset();Logger.Errors.Clear();Logger.Warnings.Clear();RPC.Sent.Clear();AmongUsClient.Instance.Packets.Clear();AmongUsClient.Instance.AmHost=true;PlayerCatch.HasMod=false;CustomRoleManager.AllRolesInfo.Clear();var i=AuditDefs.EliminatorDefinition.RoleInfo;CustomRoleManager.AllRolesInfo.Add(i.RoleName,i);Options.CreateRoleOption(CustomRoleManager.AllRolesInfo.Values.OrderBy(i=>i.ConfigId),CustomRoleTypes.Neutral);}
static void RenameValues(){Options.CustomRoleSpawnChances[CustomRoles.Eliminator].SetValue(5);Options.CustomRoleCounts[CustomRoles.Eliminator].SetValue(2);OptionItem.FastOptions[993010].SetValue(24,false);OptionItem.FastOptions[993011].SetValue(7,false);OptionItem.FastOptions[993012].SetValue(1,false);}
static void RenameCheckValues(){Check(Options.CustomRoleSpawnChances[CustomRoles.Eliminator].GetInt()==50&&Options.CustomRoleCounts[CustomRoles.Eliminator].GetInt()==3,"header/count values changed");Check(OptionItem.FastOptions[993010].GetFloat()==62.5f&&OptionItem.FastOptions[993011].GetInt()==8&&OptionItem.FastOptions[993012].GetBool(),"ability values changed");}
static void EliminatorRenameTests(){
Test("renamed role has the same numeric identity",()=>{RenameSetup();Check((int)CustomRoles.Eliminator==382&&AuditDefs.EliminatorDefinition.RoleInfo.ConfigId==993000,"role/config ID");});
Test("renamed role registers exactly five original settings",()=>{RenameSetup();Check(OptionItem.AllOptions.Select(o=>o.Id).OrderBy(i=>i).SequenceEqual(new[]{993000,993001,993010,993011,993012}),"settings identity changed");Check(Logger.Errors.Count==0,"registration error");});
Test("real ability-option defaults remain 30 seconds two kills survival OFF",()=>{RenameSetup();Check(OptionItem.FastOptions[993010].GetFloat()==30&&OptionItem.FastOptions[993011].GetInt()==2&&!OptionItem.FastOptions[993012].GetBool(),"default values");});
Test("saved JSON keys are option numbers rather than display names",()=>{RenameSetup();RenameValues();var json=JsonSerializer.Serialize(OptionSaver.Export());using var doc=JsonDocument.Parse(json);var values=doc.RootElement.GetProperty("PresetOptions");foreach(var id in new[]{993000,993001,993010,993011,993012})Check(values.TryGetProperty(id.ToString(),out _),"missing numeric key");Check(!json.Contains("Eliminator")&&!json.Contains("エリミネーター"),"role name serialized");});
Test("pre-rename compatible numeric JSON imports to renamed settings",()=>{RenameSetup();RenameValues();var json=JsonSerializer.Serialize(OptionSaver.Export());RenameSetup();OptionSaver.Import(JsonSerializer.Deserialize<OptionSaver.SerializableOptionsData>(json));RenameCheckValues();});
Test("all seven supported presets survive JSON export and import",()=>{RenameSetup();for(int p=0;p<7;p++){OptionItem.CurrentPreset=p;OptionItem.FastOptions[993010].SetValue(p,false);OptionItem.FastOptions[993011].SetValue(p%15,false);OptionItem.FastOptions[993012].SetValue(p%2,false);}var data=Copy(OptionSaver.Export());RenameSetup();OptionSaver.Import(data);for(int p=0;p<7;p++){OptionItem.CurrentPreset=p;Check(OptionItem.FastOptions[993010].GetValue()==p&&OptionItem.FastOptions[993011].GetValue()==p%15&&OptionItem.FastOptions[993012].GetValue()==p%2,"preset lost");}});
Test("assignment JSON stores the unchanged role ConfigId",()=>{RenameSetup();var assign=new AssignOptionItem(1993000);assign.RoleValues[0]=new(){CustomRoles.Eliminator};var data=OptionSaver.Export();Check(data.AssignOptions[assign.Id][0].SequenceEqual(new[]{993000}),"assignment identity changed");});
Test("prior numeric assignment resolves to the renamed role",()=>{RenameSetup();var assign=new AssignOptionItem(1993000);var data=Copy(OptionSaver.Export());data.AssignOptions[assign.Id][0]=new[]{993000};OptionSaver.Import(data);Check(assign.RoleValues[0].SequenceEqual(new[]{CustomRoles.Eliminator}),"assignment resolution");});
Test("compressed settings export remains numeric and imports unchanged",()=>{RenameSetup();RenameValues();var text=OptionSerializer.GenerateModOptionsString();RenameSetup();OptionSerializer.LoadModOptionsString(text);RenameCheckValues();Check(!text.Contains("Eliminator"),"name in settings string");});
Test("single-option RPC retains required-kill option ID",()=>{RenameSetup();PlayerCatch.HasMod=true;OptionItem.FastOptions[993011].SetValue(7);var packets=AmongUsClient.Instance.Packets.Select(p=>p.ToArray()).ToArray();Check(packets.Length==1&&packets[0][0]==993011,"changed RPC identity");RenameSetup();AmongUsClient.Instance.AmHost=false;foreach(var p in packets)RPC.Receive(new(p));Check(OptionItem.FastOptions[993011].GetInt()==8,"RPC value changed");});
Test("full setting synchronization keeps all five renamed role settings",()=>{RenameSetup();RenameValues();var expected=OptionItem.AllOptions.ToDictionary(o=>o.Id,o=>o.GetValue());PlayerCatch.HasMod=true;RPC.SyncCustomSettingsRPC();var data=AmongUsClient.Instance.Packets.Select(p=>p.ToArray()).ToArray();RenameSetup();AmongUsClient.Instance.AmHost=false;foreach(var p in data)RPC.Receive(new(p));Check(OptionItem.AllOptions.All(o=>expected[o.Id]==o.GetValue()),"full sync value changed");});
Test("translated setting names cannot alter numeric lookup",()=>{RenameSetup();OptionItem.FastOptions[993010].Name="translated label";Check(OptionItem.FastOptions[993010].Id==993010&&OptionSaver.Export().PresetOptions.ContainsKey(993010),"name used as identity");});
Test("existing recovered option migration excludes the new role IDs",()=>{foreach(var id in new[]{993000,993001,993010,993011,993012,993013,993014,993015,8000382})Check(!ShellOptionIds.IsRecoveredOption(id),"unrelated recovery alias");});
}
}
